-- Generated by tools/schemagen. Do not edit by hand: change the schema there
-- and run `go generate ./tools/schemagen`.
--
-- The three dialects below say the same thing. Writing them by hand is what
-- eighty migrations of this fork do, and every one of them is a place where
-- somebody has to remember three answers to one question.
--
-- The board's own tables: what a board, a card and a person are. The fork's,
-- as this product has them.

{{if .sqlite}}
-- Everybody the board knows: people, and — under their own names —
-- the agents and the sources. mfa_secret, auth_service and auth_data
-- are unused; password is written only on a hosted server, where
-- people register and log in.
--   role: Who administers this install. NULL and 'member' read the same, so
--     a row written before the column is not an admin. Closed by the
--     model — an account either administers the install or it does not —
--     so it is a CHECK. What a person may do *on a board* is a different
--     question and is answered by board_members.minimum_role.
--   kind: person, agent or source. There was no column to tell them apart,
--     and exclude_bots on the team's user list had nothing to filter on.
--     NO check: this set grows — a delegated runner wants an account of
--     its own — and SQLite cannot ALTER one in.
CREATE TABLE `users` (`id` varchar NOT NULL, `username` varchar NULL, `email` varchar NULL, `password` varchar NULL, `mfa_secret` varchar NULL, `auth_service` varchar NULL, `auth_data` varchar NULL, `props` text NULL, `role` varchar NULL, `kind` varchar NULL, `create_at` bigint NULL, `update_at` bigint NULL, `delete_at` bigint NULL, PRIMARY KEY (`id`), CONSTRAINT `users_role` CHECK (`role` IS NULL OR `role` IN ('admin', 'member')));

-- The team a board belongs to. In this product there is exactly one and
-- its id is '0' — but the column is in two hundred queries of the fork,
-- and working with teams stays as it is.
CREATE TABLE `teams` (`id` varchar NOT NULL, `signup_token` varchar NOT NULL, `settings` text NULL, `modified_by` varchar NULL, `update_at` bigint NULL, PRIMARY KEY (`id`));

-- A logged-in session. Its token is what proxy.go hands the page.
CREATE TABLE `sessions` (`id` varchar NOT NULL, `token` varchar NULL, `user_id` varchar NULL, `props` text NULL, `create_at` bigint NULL, `update_at` bigint NULL, `auth_service` varchar NULL, PRIMARY KEY (`id`));

-- Key and value, for the handful of things the server records about itself —
-- among them the install's switches: whether it runs agents, and whether it
-- says so when one waits (machinesettings.go).
CREATE TABLE `system_settings` (`id` varchar NOT NULL, `value` text NULL, PRIMARY KEY (`id`));

-- A board.
--   channel_id: A remnant of the Mattermost plugin. Nothing writes it.
--   type: O — open, P — private.
--   properties: The board's own automation lives here — columns, flows,
--     prompt and the records of which field is which. JSON on purpose:
--     it travels with the board, into an export and into a template.
--   card_properties: The schema of a card's fields. The product's main denormalisation, and
--     deliberately left alone: the whole webapp filters and groups on it.
CREATE TABLE `boards` (`id` varchar NOT NULL, `insert_at` datetime NOT NULL DEFAULT (STRFTIME('%Y-%m-%d %H:%M:%f', 'NOW')), `team_id` varchar NOT NULL, `channel_id` varchar NULL, `created_by` varchar NULL, `modified_by` varchar NULL, `type` varchar NOT NULL, `title` text NOT NULL, `description` text NULL, `icon` varchar NULL, `show_description` boolean NULL, `is_template` boolean NULL, `template_version` int NULL DEFAULT (0), `properties` text NULL, `card_properties` text NULL, `create_at` bigint NULL, `update_at` bigint NULL, `delete_at` bigint NULL, `minimum_role` varchar NOT NULL DEFAULT (''), PRIMARY KEY (`id`));

CREATE INDEX `idx_boards_team_id_is_template` ON `boards` (`team_id`, `is_template`);

CREATE INDEX `idx_boards_channel_id` ON `boards` (`channel_id`);

-- Every version of every board, one row per edit, never pruned. The
-- upstream's audit and undo mechanism; this product's undo is in the page
-- (frontend/src/undomanager.ts) and there is no history screen, so whether
-- to keep these three tables at all is a decision worth taking on its
-- own rather than inside a collapse.
--   channel_id: A remnant of the Mattermost plugin. Nothing writes it.
--   type: O — open, P — private.
--   properties: The board's own automation lives here — columns, flows,
--     prompt and the records of which field is which. JSON on purpose:
--     it travels with the board, into an export and into a template.
--   card_properties: The schema of a card's fields. The product's main denormalisation, and
--     deliberately left alone: the whole webapp filters and groups on it.
CREATE TABLE `boards_history` (`id` varchar NOT NULL, `insert_at` datetime NOT NULL DEFAULT (STRFTIME('%Y-%m-%d %H:%M:%f', 'NOW')), `team_id` varchar NOT NULL, `channel_id` varchar NULL, `created_by` varchar NULL, `modified_by` varchar NULL, `type` varchar NOT NULL, `title` text NOT NULL, `description` text NULL, `icon` varchar NULL, `show_description` boolean NULL, `is_template` boolean NULL, `template_version` int NULL DEFAULT (0), `properties` text NULL, `card_properties` text NULL, `create_at` bigint NULL, `update_at` bigint NULL, `delete_at` bigint NULL, `minimum_role` varchar NOT NULL DEFAULT (''), PRIMARY KEY (`id`, `insert_at`));

-- Everything on a board: cards, views, comments, text, attachments. A
-- card is a row here with type='card', and it is what every table this
-- application owns points at.
--   id: Nullable, which a primary key makes impossible in practice — but this
--     is what the migrations leave, and reproducing it is the point.
--   parent_id: The tree inside a board: a comment or a text block hangs off a card.
--   schema: A version number for the row's own shape. Backticked by the fork's
--     queries on MySQL, where `schema` is reserved.
--   fields: The card's field values, {property_id: value}.
CREATE TABLE `blocks` (`id` varchar NOT NULL, `insert_at` datetime NOT NULL DEFAULT (STRFTIME('%Y-%m-%d %H:%M:%f', 'NOW')), `parent_id` varchar NULL, `schema` bigint NULL, `type` text NULL, `title` text NULL, `fields` text NULL, `create_at` bigint NULL, `update_at` bigint NULL, `delete_at` bigint NULL, `modified_by` varchar NULL, `channel_id` varchar NULL, `created_by` varchar NULL, `board_id` varchar NULL, PRIMARY KEY (`id`));

CREATE INDEX `idx_blocks_board_id_parent_id` ON `blocks` (`board_id`, `parent_id`);

-- Every version of every block. See boards_history.
--   id: Nullable, which a primary key makes impossible in practice — but this
--     is what the migrations leave, and reproducing it is the point.
--   parent_id: The tree inside a board: a comment or a text block hangs off a card.
--   schema: A version number for the row's own shape. Backticked by the fork's
--     queries on MySQL, where `schema` is reserved.
--   fields: The card's field values, {property_id: value}.
CREATE TABLE `blocks_history` (`id` varchar NOT NULL, `insert_at` datetime NOT NULL DEFAULT (STRFTIME('%Y-%m-%d %H:%M:%f', 'NOW')), `parent_id` varchar NULL, `schema` bigint NULL, `type` text NULL, `title` text NULL, `fields` text NULL, `create_at` bigint NULL, `update_at` bigint NULL, `delete_at` bigint NULL, `modified_by` varchar NULL, `channel_id` varchar NULL, `created_by` varchar NULL, `board_id` varchar NULL, PRIMARY KEY (`id`, `insert_at`));

-- Who is on a board, and what they may do there.
CREATE TABLE `board_members` (`board_id` varchar NOT NULL, `user_id` varchar NOT NULL, `roles` varchar NULL, `scheme_admin` boolean NULL, `scheme_editor` boolean NULL, `scheme_commenter` boolean NULL, `scheme_viewer` boolean NULL, PRIMARY KEY (`board_id`, `user_id`));

CREATE INDEX `idx_board_members_user_id` ON `board_members` (`user_id`);

-- Who joined or left a board, and when.
CREATE TABLE `board_members_history` (`board_id` varchar NOT NULL, `user_id` varchar NOT NULL, `action` varchar NULL, `insert_at` datetime NOT NULL DEFAULT (STRFTIME('%Y-%m-%d %H:%M:%f', 'NOW')), PRIMARY KEY (`board_id`, `user_id`, `insert_at`));

CREATE INDEX `idx_board_members_history_user_id` ON `board_members_history` (`user_id`);

CREATE INDEX `idx_board_members_history_board_id_user_id` ON `board_members_history` (`board_id`, `user_id`);

-- A group of boards in the sidebar.
CREATE TABLE `categories` (`id` varchar NOT NULL, `name` varchar NOT NULL, `user_id` varchar NOT NULL, `team_id` varchar NOT NULL, `channel_id` varchar NULL, `create_at` bigint NULL, `update_at` bigint NULL, `delete_at` bigint NULL, `collapsed` boolean NULL DEFAULT (false), `type` varchar NULL, `sort_order` bigint NULL, PRIMARY KEY (`id`));

CREATE INDEX `idx_categories_user_id_team_id` ON `categories` (`user_id`, `team_id`);

-- Which board sits in which sidebar group. The surrogate id is
-- upstream's; the row is really the pair, which the unique index says.
CREATE TABLE `category_boards` (`id` varchar NOT NULL, `user_id` varchar NOT NULL, `category_id` varchar NOT NULL, `board_id` varchar NOT NULL, `create_at` bigint NULL, `update_at` bigint NULL, `sort_order` bigint NULL, `hidden` boolean NULL, PRIMARY KEY (`id`));

CREATE UNIQUE INDEX `unique_user_category_board` ON `category_boards` (`user_id`, `board_id`);

-- A board's public link. The id is the board's, so this is one-to-one.
CREATE TABLE `sharing` (`id` varchar NOT NULL, `enabled` boolean NULL, `token` varchar NULL, `modified_by` varchar NULL, `update_at` bigint NULL, PRIMARY KEY (`id`));

-- An attachment. It has no primary key, which is what the migrations
-- leave: 000041 was where one would have been added, and this is a
-- reproduction rather than a repair.
--   id: Widened from the 26 the ladder declared, and the one place this schema
--     deliberately differs from it. It was already too narrow: utils.NewID
--     has always produced 27 characters, so on MySQL and Postgres every
--     attachment id was truncated by one. UUIDv7 needs 36, which is what
--     every other id column already holds.
CREATE TABLE `file_info` (`id` varchar NOT NULL, `create_at` bigint NOT NULL, `delete_at` bigint NULL, `name` text NOT NULL, `extension` varchar NOT NULL, `size` bigint NOT NULL, `archived` boolean NULL, `path` varchar NULL);

-- What a person chose, per category and name — the page's settings
-- among them (theme, language, the last board), so on a server everybody
-- has their own. The machine's switches are system_settings.
CREATE TABLE `preferences` (`userid` varchar NOT NULL, `category` varchar NOT NULL, `name` varchar NOT NULL, `value` text NULL, PRIMARY KEY (`userid`, `category`, `name`));

CREATE INDEX `idx_preferences_category` ON `preferences` (`category`);

CREATE INDEX `idx_preferences_name` ON `preferences` (`name`);

-- Who is watching a block, for the notification service.
CREATE TABLE `subscriptions` (`block_type` varchar NULL, `block_id` varchar NOT NULL, `subscriber_type` varchar NULL, `subscriber_id` varchar NOT NULL, `notified_at` bigint NULL, `create_at` bigint NULL, `delete_at` bigint NULL, PRIMARY KEY (`block_id`, `subscriber_id`));

CREATE INDEX `idx_subscriptions_subscriber_id` ON `subscriptions` (`subscriber_id`);

-- A block that has changed and whose watchers have not been told yet.
CREATE TABLE `notification_hints` (`block_type` varchar NULL, `block_id` varchar NOT NULL, `modified_by_id` varchar NULL, `create_at` bigint NULL, `notify_at` bigint NULL, PRIMARY KEY (`block_id`));
{{end}}

