--   card_properties: The schema of a card's fields. The product's main denormalisation, and
--     deliberately left alone: the whole webapp filters and groups on it.
CREATE TABLE "boards" ("id" character varying(36) NOT NULL, "insert_at" timestamptz NOT NULL DEFAULT NOW(), "team_id" character varying(36) NOT NULL, "channel_id" character varying(36) NULL, "created_by" character varying(36) NULL, "modified_by" character varying(36) NULL, "type" character varying(1) NOT NULL, "title" text NOT NULL, "description" text NULL, "icon" character varying(256) NULL, "show_description" boolean NULL, "is_template" boolean NULL, "template_version" integer NULL DEFAULT 0, "properties" text NULL, "card_properties" text NULL, "create_at" bigint NULL, "update_at" bigint NULL, "delete_at" bigint NULL, "minimum_role" character varying(36) NOT NULL DEFAULT '', PRIMARY KEY ("id"));

-- A board.
--   channel_id: A remnant of the Mattermost plugin. Nothing writes it.
--   type: O — open, P — private.
--   properties: The board's own automation lives here — columns, flows,
--     prompt and the records of which field is which. JSON on purpose:
--     it travels with the board, into an export and into a template.
--   card_properties: The schema of a card's fields. The product's main denormalisation, and
--     deliberately left alone: the whole webapp filters and groups on it.
CREATE INDEX "idx_boards_team_id_is_template" ON "boards" ("team_id", "is_template");

-- A board.
--   channel_id: A remnant of the Mattermost plugin. Nothing writes it.
--   type: O — open, P — private.
--   properties: The board's own automation lives here — columns, flows,
--     prompt and the records of which field is which. JSON on purpose:
--     it travels with the board, into an export and into a template.
--   card_properties: The schema of a card's fields. The product's main denormalisation, and
--     deliberately left alone: the whole webapp filters and groups on it.
CREATE INDEX "idx_boards_channel_id" ON "boards" ("channel_id");

-- Every version of every board, one row per edit, never pruned. The
-- upstream's audit and undo mechanism; this product's undo is in the page
-- (frontend/src/undomanager.ts) and there is no history screen, so whether
-- to keep these three tables at all is a decision worth taking on its
-- own rather than inside a collapse.
--   channel_id: A remnant of the Mattermost plugin. Nothing writes it.
--   type: O — open, P — private.
--   properties: The board's own automation lives here — columns, flows,
--     prompt and the records of which field is which. JSON on purpose:
--     it travels with the board, into an export and into a template.
--   card_properties: The schema of a card's fields. The product's main denormalisation, and
--     deliberately left alone: the whole webapp filters and groups on it.
CREATE TABLE "boards_history" ("id" character varying(36) NOT NULL, "insert_at" timestamptz NOT NULL DEFAULT NOW(), "team_id" character varying(36) NOT NULL, "channel_id" character varying(36) NULL, "created_by" character varying(36) NULL, "modified_by" character varying(36) NULL, "type" character varying(1) NOT NULL, "title" text NOT NULL, "description" text NULL, "icon" character varying(256) NULL, "show_description" boolean NULL, "is_template" boolean NULL, "template_version" integer NULL DEFAULT 0, "properties" text NULL, "card_properties" text NULL, "create_at" bigint NULL, "update_at" bigint NULL, "delete_at" bigint NULL, "minimum_role" character varying(36) NOT NULL DEFAULT '', PRIMARY KEY ("id", "insert_at"));

-- Everything on a board: cards, views, comments, text, attachments. A
-- card is a row here with type='card', and it is what every table this
-- application owns points at.
--   id: Nullable, which a primary key makes impossible in practice — but this
--     is what the migrations leave, and reproducing it is the point.
--   parent_id: The tree inside a board: a comment or a text block hangs off a card.
--   schema: A version number for the row's own shape. Backticked by the fork's
--     queries on MySQL, where `schema` is reserved.
--   fields: The card's field values, {property_id: value}.
CREATE TABLE "blocks" ("id" character varying(36) NOT NULL, "insert_at" timestamptz NOT NULL DEFAULT NOW(), "parent_id" character varying(36) NULL, "schema" bigint NULL, "type" text NULL, "title" text NULL, "fields" text NULL, "create_at" bigint NULL, "update_at" bigint NULL, "delete_at" bigint NULL, "modified_by" character varying(36) NULL, "channel_id" character varying(36) NULL, "created_by" character varying(36) NULL, "board_id" character varying(36) NULL, PRIMARY KEY ("id"));

-- Everything on a board: cards, views, comments, text, attachments. A
-- card is a row here with type='card', and it is what every table this
-- application owns points at.
--   id: Nullable, which a primary key makes impossible in practice — but this
--     is what the migrations leave, and reproducing it is the point.
--   parent_id: The tree inside a board: a comment or a text block hangs off a card.
--   schema: A version number for the row's own shape. Backticked by the fork's
--     queries on MySQL, where `schema` is reserved.
--   fields: The card's field values, {property_id: value}.
CREATE INDEX "idx_blocks_board_id_parent_id" ON "blocks" ("board_id", "parent_id");

-- Every version of every block. See boards_history.
--   id: Nullable, which a primary key makes impossible in practice — but this
--     is what the migrations leave, and reproducing it is the point.
--   parent_id: The tree inside a board: a comment or a text block hangs off a card.
--   schema: A version number for the row's own shape. Backticked by the fork's
--     queries on MySQL, where `schema` is reserved.
--   fields: The card's field values, {property_id: value}.
CREATE TABLE "blocks_history" ("id" character varying(36) NOT NULL, "insert_at" timestamptz NOT NULL DEFAULT NOW(), "parent_id" character varying(36) NULL, "schema" bigint NULL, "type" text NULL, "title" text NULL, "fields" text NULL, "create_at" bigint NULL, "update_at" bigint NULL, "delete_at" bigint NULL, "modified_by" character varying(36) NULL, "channel_id" character varying(36) NULL, "created_by" character varying(36) NULL, "board_id" character varying(36) NULL, PRIMARY KEY ("id", "insert_at"));

-- Who is on a board, and what they may do there.
CREATE TABLE "board_members" ("board_id" character varying(36) NOT NULL, "user_id" character varying(36) NOT NULL, "roles" character varying(64) NULL, "scheme_admin" boolean NULL, "scheme_editor" boolean NULL, "scheme_commenter" boolean NULL, "scheme_viewer" boolean NULL, PRIMARY KEY ("board_id", "user_id"));

-- Who is on a board, and what they may do there.
CREATE INDEX "idx_board_members_user_id" ON "board_members" ("user_id");

-- Who joined or left a board, and when.
CREATE TABLE "board_members_history" ("board_id" character varying(36) NOT NULL, "user_id" character varying(36) NOT NULL, "action" character varying(10) NULL, "insert_at" timestamptz NOT NULL DEFAULT NOW(), PRIMARY KEY ("board_id", "user_id", "insert_at"));

-- Who joined or left a board, and when.
CREATE INDEX "idx_board_members_history_user_id" ON "board_members_history" ("user_id");

-- Who joined or left a board, and when.
CREATE INDEX "idx_board_members_history_board_id_user_id" ON "board_members_history" ("board_id", "user_id");

-- A group of boards in the sidebar.
CREATE TABLE "categories" ("id" character varying(36) NOT NULL, "name" character varying(100) NOT NULL, "user_id" character varying(36) NOT NULL, "team_id" character varying(36) NOT NULL, "channel_id" character varying(36) NULL, "create_at" bigint NULL, "update_at" bigint NULL, "delete_at" bigint NULL, "collapsed" boolean NULL DEFAULT false, "type" character varying(64) NULL, "sort_order" bigint NULL, PRIMARY KEY ("id"));

-- A group of boards in the sidebar.
CREATE INDEX "idx_categories_user_id_team_id" ON "categories" ("user_id", "team_id");

-- Which board sits in which sidebar group. The surrogate id is
-- upstream's; the row is really the pair, which the unique index says.
CREATE TABLE "category_boards" ("id" character varying(36) NOT NULL, "user_id" character varying(36) NOT NULL, "category_id" character varying(36) NOT NULL, "board_id" character varying(36) NOT NULL, "create_at" bigint NULL, "update_at" bigint NULL, "sort_order" bigint NULL, "hidden" boolean NULL, PRIMARY KEY ("id"));

-- Which board sits in which sidebar group. The surrogate id is
-- upstream's; the row is really the pair, which the unique index says.
CREATE UNIQUE INDEX "unique_user_category_board" ON "category_boards" ("user_id", "board_id");

-- A board's public link. The id is the board's, so this is one-to-one.
CREATE TABLE "sharing" ("id" character varying(36) NOT NULL, "enabled" boolean NULL, "token" character varying(100) NULL, "modified_by" character varying(36) NULL, "update_at" bigint NULL, PRIMARY KEY ("id"));

-- An attachment. It has no primary key, which is what the migrations
-- leave: 000041 was where one would have been added, and this is a
-- reproduction rather than a repair.
--   id: Widened from the 26 the ladder declared, and the one place this schema
--     deliberately differs from it. It was already too narrow: utils.NewID
--     has always produced 27 characters, so on MySQL and Postgres every
--     attachment id was truncated by one. UUIDv7 needs 36, which is what
--     every other id column already holds.
CREATE TABLE "file_info" ("id" character varying(36) NOT NULL, "create_at" bigint NOT NULL, "delete_at" bigint NULL, "name" text NOT NULL, "extension" character varying(50) NOT NULL, "size" bigint NOT NULL, "archived" boolean NULL, "path" character varying(512) NULL);

-- What a person chose, per category and name — the page's settings
-- among them (theme, language, the last board), so on a server everybody
-- has their own. The machine's switches are system_settings.
CREATE TABLE "preferences" ("userid" character varying(36) NOT NULL, "category" character varying(32) NOT NULL, "name" character varying(32) NOT NULL, "value" text NULL, PRIMARY KEY ("userid", "category", "name"));

-- What a person chose, per category and name — the page's settings
-- among them (theme, language, the last board), so on a server everybody
-- has their own. The machine's switches are system_settings.
CREATE INDEX "idx_preferences_category" ON "preferences" ("category");

-- What a person chose, per category and name — the page's settings
-- among them (theme, language, the last board), so on a server everybody
-- has their own. The machine's switches are system_settings.
CREATE INDEX "idx_preferences_name" ON "preferences" ("name");

-- Who is watching a block, for the notification service.
CREATE TABLE "subscriptions" ("block_type" character varying(10) NULL, "block_id" character varying(36) NOT NULL, "subscriber_type" character varying(10) NULL, "subscriber_id" character varying(36) NOT NULL, "notified_at" bigint NULL, "create_at" bigint NULL, "delete_at" bigint NULL, PRIMARY KEY ("block_id", "subscriber_id"));

-- Who is watching a block, for the notification service.
CREATE INDEX "idx_subscriptions_subscriber_id" ON "subscriptions" ("subscriber_id");

-- A block that has changed and whose watchers have not been told yet.
CREATE TABLE "notification_hints" ("block_type" character varying(10) NULL, "block_id" character varying(36) NOT NULL, "modified_by_id" character varying(36) NULL, "create_at" bigint NULL, "notify_at" bigint NULL, PRIMARY KEY ("block_id"));
{{end}}
